<template><div class="page"><div class="crumb"><button @click="router.push('/student/dashboard')">我的课程</button><span>›</span><strong>{{ course?.name || '课程作业' }}</strong></div><header><p>{{ course?.code }}</p><h1>{{ course?.name || '课程作业' }}</h1><span>查看作业要求、组队状态和提交情况</span></header><div v-if="errorMessage" class="error">{{ errorMessage }}</div><section class="panel"><div class="panel-head"><h2>课程作业</h2><span>{{ assignments.length }} 项作业</span></div><button v-for="item in assignments" :key="item.id" class="assignment" @click="router.push(`/student/assignment/${item.id}`)"><div class="icon">作业</div><div class="main"><h3>{{ item.title }}</h3><p>{{ item.description || '暂无作业说明' }}</p></div><div class="deadline"><small>截止时间</small><b>{{ formatDate(item.deadline) }}</b></div><i :class="item.teamFormation ? 'forming' : (item.submitted ? 'done' : 'pending')">{{ item.teamFormation ? '组队中' : (item.submitted ? '已提交' : '待提交') }}</i></button><el-empty v-if="!assignments.length" description="暂无作业" /></section></div></template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { getAssignments,getCourses } from '@/api/student';import { getErrorMessage } from '@/api/response'
const route=useRoute();const router=useRouter();const courses=ref([]);const assignments=ref([]);const errorMessage=ref('');const course=computed(()=>courses.value.find(item=>String(item.id)===String(route.params.courseId)));const formatDate=value=>value?new Date(value).toLocaleDateString('zh-CN'):'未设置';onMounted(async()=>{try{[courses.value,assignments.value]=await Promise.all([getCourses(),getAssignments(route.params.courseId)])}catch(error){errorMessage.value=getErrorMessage(error,'课程作业加载失败')}})
</script>
<style scoped>.page{max-width:1120px;margin:0 auto}.crumb{display:flex;gap:8px;margin-bottom:25px;color:#8795a6;font-size:14px}.crumb button{border:0;background:none;color:inherit;cursor:pointer}.crumb strong{color:#263b53}header{margin-bottom:28px}header p{margin:0 0 8px;color:#6b9ed8;font-size:12px}header h1{margin:0 0 8px;color:#263b53;font-size:30px}header span{color:#8795a6}.panel{overflow:hidden;border-radius:9px;background:#fff;box-shadow:0 3px 12px #263b5310}.panel-head{display:flex;justify-content:space-between;padding:19px 22px;border-bottom:1px solid #edf1f4}.panel-head h2{margin:0;color:#263b53;font-size:18px}.panel-head span{color:#6b9ed8;font-size:13px}.assignment{display:flex;width:100%;align-items:center;gap:16px;padding:19px 22px;border:0;border-bottom:1px solid #edf1f4;text-align:left;background:#fff;cursor:pointer}.assignment:hover{background:#f8fbfd}.icon{display:grid;width:42px;height:42px;place-items:center;border-radius:9px;color:#356798;background:#eaf2fa;font-size:12px}.main{flex:1}.main h3{margin:0 0 7px;color:#334155;font-size:16px}.main p{margin:0;color:#98a5b3;font-size:13px}.deadline{display:grid;gap:5px;color:#98a5b3;font-size:12px}.deadline b{color:#52657a;font-weight:500}.assignment i{padding:5px 11px;border-radius:99px;font-size:12px;font-style:normal}.forming{color:#356798;background:#eaf2fa}.done{color:#35845a;background:#edf8f1}.pending{color:#9b6b29;background:#fff6e8}.error{padding:12px;color:#b42318;background:#fff5f5}@media(max-width:650px){.assignment{align-items:flex-start;flex-wrap:wrap}.deadline{margin-left:58px}.assignment i{margin-left:auto}}</style>
